import csv

def clean_row(row):
    name = row["name"].strip().title()
    event = row["event"].strip()
    seats_text = row["seats"].strip()
    email = row["email"].strip().lower()

    if name == "" or event == "" or email == "":
        return None

    try:
        seats = int(seats_text)
    except ValueError:
        return None

    if seats < 1:
        return None

    return {"name": name, "event": event, "seats": seats, "email": email}

with open("data/registrations.csv", "r") as file:
    reader = csv.DictReader(file)
    for row in reader:
        print(clean_row(row))

